def test_utf8_spans_reconstruct_original_bytes():
    context = prepare("## FR-001\nSécurité\n## AC-001\nVérifié")
    original = "## FR-001\nSécurité\n## AC-001\nVérifié".encode()
    for section in context.sections:
        if section.role == "spec":
            assert original[section.start_byte : section.end_byte].decode() == section.text

@pytest.mark.parametrize(
    "corruption", ["omitted", "foreign", "duplicate", "citation", "plan", "sections"]
)
def test_claimed_success_without_grounding_is_incomplete(corruption):
    context = prepare()
    raw = response(context)
    if corruption == "omitted":
        raw["conclusions"] = []
    elif corruption == "foreign":
        raw["conclusions"][0]["requirement_id"] = "other:FR-001"
    elif corruption == "duplicate":
        raw["conclusions"] *= 2
    elif corruption == "citation":
        raw["conclusions"][0]["source_citations"][0]["excerpt"] = "invented contract"
    elif corruption == "plan":
        raw["conclusions"][0]["plan_citations"] = []
    else:
        raw["reviewed_section_ids"] = []
    result = validate_review_result(context, [json.dumps(raw)])
    assert not result.complete and not result.ready

@pytest.mark.parametrize(
    "link",
    [
        "Read [contract](../../../contract.md).",
        "Read [contract][contract-ref].\n\n[contract-ref]: ../../../contract.md",
        "Read [contract].\n\n[contract]: ../../../contract.md",
        "| Purpose | Contract |\n|---|---|\n| Rule | [contract](../../../contract.md) |",
    ],
)
def test_real_inline_reference_and_table_links_load_complete_closure(
    tmp_path: Path, link: str
) -> None:
    tail = "# Contract\n" + "Full context. " * 800 + "\n## Late rule\nFR-099 Retain 24 hours."
    _write(tmp_path, "contract.md", "Read [nested](nested.md).\nFR-002 First rule.")
    _write(tmp_path, "nested.md", tail)
    prepared = _prepare(tmp_path, "FR-001 Canonical source.\n\n" + link)
    assert prepared.complete, prepared.errors
    assert prepared.source_hashes["nested.md"] == content_hash(tail)
    assert "".join(s.text for s in prepared.sections if s.source == "nested.md") == tail
    assert f"{prepared.feature}:FR-099" in {r.requirement_id for r in prepared.requirements}

@pytest.mark.parametrize(
    ("link", "error"),
    [
        ("Read [missing](../../../missing.md).", "unread_source:missing.md:FileNotFoundError"),
        ("Read [outside](../../../../outside.md).", "contract_outside_project:"),
        ("Read [remote](https://example.org/contract.md).", "external_contract_not_loaded:"),
    ],
)
def test_true_unavailable_normative_contracts_fail_closed(
    tmp_path: Path, link: str, error: str
) -> None:
    prepared = _prepare(tmp_path, "FR-001 Canonical rule.\n\n" + link)
    assert not prepared.complete
    assert any(error in item for item in prepared.errors)

def test_later_normative_edge_promotes_inspected_source_and_traverses_it(tmp_path: Path) -> None:
    _write(tmp_path, "source.md", "FR-099 Contract rule.\nRead [nested](nested.md).")
    _write(tmp_path, "nested.md", "FR-098 Nested mandatory rule.")
    prepared = _prepare(
        tmp_path,
        "FR-001 Rule.\n\nInspect [source](../../../source.md).\n\n"
        "Read [contract](../../../source.md).",
    )
    assert prepared.complete, prepared.errors
    assert {s.role for s in prepared.sections if s.source == "source.md"} == {"reference"}
    assert "nested.md" in prepared.source_hashes
    assert f"{prepared.feature}:FR-098" in {r.requirement_id for r in prepared.requirements}

def test_canonical_sources_are_never_demoted_by_inspection_links(tmp_path: Path) -> None:
    prepared = _prepare(tmp_path, "FR-001 Rule.\n\nInspect [constitution](../../constitution.md).")
    assert prepared.complete
    assert {s.role for s in prepared.sections if s.source == ".specs/constitution.md"} == {
        "constitution"
    }

@pytest.mark.parametrize("kind", ["spec", "plan"])
@pytest.mark.parametrize("change", ["source", "model", "kind", "config"])
def test_short_scope_does_not_reuse_stale_or_foreign_evidence(
    tmp_path: Path, kind: Literal["spec", "plan"], change: str
) -> None:
    """Canonical resolution cannot bypass current source, model, purpose or dependency checks."""
    feature = _project(tmp_path)
    prepared = prepare_feature_review(tmp_path, FEATURE, kind, "reviewer/actual")
    receipt, path = ingest_feature_review(
        tmp_path, FEATURE, kind, [_raw(prepared)], model="reviewer/actual"
    )
    assert receipt.ready
    model = "reviewer/actual"
    expected: Literal["spec", "plan"] = kind
    if change == "source":
        (feature / "spec.md").write_text("## FR-001\nRetain exports forever.\n")
    elif change == "model":
        model = "reviewer/other"
    elif change == "kind":
        expected = "plan" if kind == "spec" else "spec"
    else:
        config = tmp_path / ".specs/semantic/config.yaml"
        config.parent.mkdir()
        config.write_text("review_max_chars: 100000\n")
    assert not verify_feature_review(
        tmp_path, "retention", path, model=model, expected_kind=expected
    )

@pytest.mark.parametrize("version", ["POLICY_VERSION", "SCHEMA_VERSION", "PROMPT_VERSION"])
def test_short_scope_rejects_receipts_from_a_prior_review_protocol(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch, version: str
) -> None:
    """Protocol releases invalidate an otherwise unchanged canonical receipt through aliases."""
    _project(tmp_path)
    prepared = prepare_feature_review(tmp_path, FEATURE, "spec", "reviewer/actual")
    receipt, path = ingest_feature_review(
        tmp_path, FEATURE, "spec", [_raw(prepared)], model="reviewer/actual"
    )
    assert receipt.ready
    assert verify_feature_review(
        tmp_path, "retention", path, model="reviewer/actual", expected_kind="spec"
    )
    monkeypatch.setattr(review_context, version, "future-protocol-version")
    assert not verify_feature_review(
        tmp_path, "retention", path, model="reviewer/actual", expected_kind="spec"
    )

@pytest.mark.parametrize("command", ["spec-check", "spec-fix"])
def test_new_existing_feature_goals_freeze_same_canonical_identity(
    tmp_path: Path, command: str
) -> None:
    """A new short request compiles the same immutable hash and bindings as its actual owner."""
    _project(tmp_path)
    flags = "--model=reviewer/actual --review-max-chars=200000"
    numbered = compile_command_goal(
        command, project_root=tmp_path, livespec_root=ROOT, feature=FEATURE, flags=flags
    )
    short = compile_command_goal(
        command, project_root=tmp_path, livespec_root=ROOT, feature="retention", flags=flags
    )
    assert short.goal_hash == numbered.goal_hash
    assert short.canonical_json == numbered.canonical_json
    assert short.payload["feature"] == FEATURE

@pytest.mark.parametrize("boundary", ["## Requirements", "---", "***", "___", "### Detail"])
def test_legacy_band_ends_before_body_status_and_fenced_examples(boundary: str) -> None:
    initial = (
        "---\nstatus: Approved\n---\n# Feature\n- **Status:** Approved\n"
        "```text\n- **Status:** In Progress\n```\n"
        f"{boundary}\n- **Status:** In Progress\n"
    )
    metadata_change = initial.replace("status: Approved", "status: Implemented").replace(
        "- **Status:** Approved", "- **Status:** Implemented"
    )
    assert normative_hash(initial, lifecycle_document=True) == normative_hash(
        metadata_change, lifecycle_document=True
    )
    assert normative_hash(initial, lifecycle_document=True) != normative_hash(
        initial.replace("In Progress", "Implemented"), lifecycle_document=True
    )

@pytest.mark.parametrize(
    "source_slug", ["001-auto-llm-review", "077-penflow-cumulative-verdict-consumer"]
)
@pytest.mark.parametrize("band", ["explicit", "legacy"])
@pytest.mark.parametrize("newline", ["\n", "\r\n"], ids=["LF", "CRLF"])
def test_first_and_subsequent_finalization_preserve_copied_header_body(
    tmp_path: Path, source_slug: str, band: str, newline: str
) -> None:
    """Real finalization changes only metadata, preserving immutable source copies and comments."""
    source = ROOT / ".specs/features" / source_slug / "spec.md"
    source_bytes = source.read_bytes()
    lines = source_bytes.decode().splitlines(keepends=True)
    if band == "explicit":
        title = next(index for index, line in enumerate(lines) if line.startswith("# "))
        lines.insert(title + 1, "\n## Header\n")
    copied = ("".join(lines) + "\n<!-- Historical body comment must remain. -->\n").replace(
        "\n", newline
    )
    specs = _make_specs_tree(tmp_path)
    request = replace(_implement_request(), status="In Progress", run_id="first")
    spec = specs / "features" / request.feature_slug / "spec.md"
    spec.write_bytes(copied.encode())

    def prepare() -> PreparedReview:
        return prepare_review_context(
            request.feature_slug,
            {"spec": spec.read_bytes().decode(), "plan": "Implement the declared contract."},
            model="reviewer/actual",
            max_chars=200000,
        )

    before = prepare()
    receipt = validate_review_result(before, [_raw(before)])
    assert receipt.ready
    metadata = lifecycle_metadata(copied)
    mutable = {field.index for field in (*metadata.frontmatter_fields, *metadata.header_fields)}
    original_lines = copied.encode().splitlines(keepends=True)
    for operation in (request, replace(request, status="Implemented", run_id="subsequent")):
        apply_finalization(tmp_path, operation)
        current_lines = spec.read_bytes().splitlines(keepends=True)
        assert len(current_lines) == len(original_lines)
        assert all(
            original_lines[index] == line
            for index, line in enumerate(current_lines)
            if index not in mutable
        )
        assert verify_review_receipt(receipt, prepare())
    assert before.source_hashes != prepare().source_hashes
    assert source.read_bytes() == source_bytes
